db = SessionLocal()
count = 0
for m in data:
    rm = RobotMap(
        robot_sn=ROBOT_SN,
        mapping_id=m["id"],
        continue_mapping=m.get("continue_mapping", False),
        thumbnail_url=m.get("thumbnail_url"),
        image_url=m.get("image_url"),
        grid_origin_x=m.get("grid_origin_x", 0.0),
        grid_origin_y=m.get("grid_origin_y", 0.0),
        grid_resolution=m.get("grid_resolution", 0.0),
        url=m.get("url"),
        start_time=m.get("start_time"),
        end_time=m.get("end_time"),
        state=m.get("state"),
        bag_url=m.get("bag_url"),
        download_url=m.get("download_url"),
        pbstream_url=m.get("pbstream_url"),
        trajectories_url=m.get("trajectories_url"),
        properties_url=m.get("properties_url"),
    )
    db.add(rm)
    count += 1

db.commit()
print(f"{count}건 삽입 완료")

total = db.query(RobotMap).count()
finished = db.query(RobotMap).filter(RobotMap.state == "finished").count()
cancelled = db.query(RobotMap).filter(RobotMap.state == "cancelled").count()
print(f"총 {total}건 (finished={finished}, cancelled={cancelled})")
db.close()
